import React, { useMemo } from "react"
import { Link } from "gatsby"

import Shell from "../components/layout/Shell"
import Panel from "../components/layout/Panel"
import Breadcrumb from "../components/ui/Breadcrumb"
import { DataTable, Delta, MetricCard, Sparkline, TickerMark } from "../components/ui"

import {
  INDICES,
  getMarketBreadth,
  getMarketSentiment,
  getMarketStatus,
  getWatchlist,
} from "../data/markets"
import { describeSource } from "../data/source"

/**
 * Markets.
 *
 * Where the tape stands: the benchmarks, how broad the move is, and which
 * names are carrying it.
 *
 * THE HONEST NOTE THIS PAGE HAS TO CARRY. The free Massive plan includes no
 * index entitlement, so the benchmark tiles quote liquid ETFs that track the
 * indices — SPY for the S&P, QQQ for the NASDAQ. They move with the index and
 * are the right instrument to watch, but they are NOT the index: SPY trades
 * near a tenth of the S&P's level, and there is tracking error besides. Every
 * tile names the instrument it is quoting. Printing "S&P 500" over a SPY level
 * would be the kind of small lie that costs trust in every other number here.
 *
 * WHY BREADTH SITS BESIDE THE LEVELS. An index can rise while most of its
 * constituents fall — a handful of large names can carry a whole benchmark.
 * Breadth is what separates a broad advance from a narrow one, so it is given
 * equal weight rather than buried under the headline figures.
 */

const DASH = "—"
const isNum = v => typeof v === "number" && Number.isFinite(v)
const usd = (v, d = 2) => (isNum(v) ? "$" + v.toFixed(d) : DASH)
const num = (v, d = 2) => (isNum(v) ? v.toFixed(d) : DASH)

function Identity({ symbol, name }) {
  return (
    <span className="identity">
      <TickerMark symbol={symbol} size={26} />
      <span className="identity__text">
        <span className="identity__symbol">{symbol}</span>
        <span className="identity__name">{name}</span>
      </span>
    </span>
  )
}

export default function MarketsPage({ location }) {
  const breadth = useMemo(() => getMarketBreadth(), [])
  const sentiment = useMemo(() => getMarketSentiment(), [])
  const status = useMemo(() => getMarketStatus(), [])
  const rows = useMemo(() => getWatchlist(), [])
  const source = useMemo(() => describeSource(), [])

  const ranked = useMemo(
    () => [...rows].sort((a, b) => (b.changePct ?? 0) - (a.changePct ?? 0)),
    [rows]
  )
  const leaders = ranked.slice(0, 5)
  const laggards = ranked.slice(-5).reverse()

  const columns = [
    {
      key: "symbol", header: "Symbol", width: "220px",
      sortValue: r => r.symbol,
      render: r => <Identity symbol={r.symbol} name={r.name} />,
    },
    {
      key: "price", header: "Price", numeric: true, align: "right",
      sortValue: r => r.price, render: r => usd(r.price),
    },
    {
      key: "changeAbs", header: "Today", align: "right", mobile: false,
      sortValue: r => r.changeAbs,
      render: r => <Delta value={r.changeAbs} digits={2} showGlyph={false} />,
    },
    {
      key: "changePct", header: "Change", align: "right",
      sortValue: r => r.changePct,
      render: r => <Delta value={r.changePct} percent digits={2} />,
    },
    {
      key: "bias", header: "Signal bias", align: "right", mobile: false,
      sortValue: r => r.bullish ?? 0,
      render: r =>
        isNum(r.bullish) && isNum(r.total) && r.total > 0 ? (
          <span className="markets__bias">{r.bullish}/{r.total} bullish</span>
        ) : (
          /* No signals is not zero signals of a direction — say nothing. */
          <span className="markets__bias markets__bias--none">no signals</span>
        ),
    },
  ]

  return (
    <Shell location={location}>
      <div className="page">
        <header className="page__head">
          <div className="page__heading">
            <Breadcrumb items={[{ label: "MarketScan", to: "/" }, { label: "Markets" }]} />
            <h1 className="page__title">Markets</h1>
            <p className="page__lede">
              Benchmark levels, how broad today&rsquo;s move is, and which names are carrying it.
            </p>
          </div>
          <div className="page__aside">
            <span className={"markets__status" + (status.isOpen ? " is-open" : "")}>
              <span className="markets__status-dot" />
              {status.label}
            </span>
            <span className="markets__status-detail">{status.detail}</span>
          </div>
        </header>

        {/* ------------------------------------------------------ benchmarks */}
        <section className="section">
          <div className="section__head">
            <div className="section__heading">
              <h2 className="section__title">Benchmarks</h2>
              <p className="section__subtitle">
                Tracked through liquid ETFs — the current data plan carries no index
                entitlement, so each tile names the instrument it is quoting.
              </p>
            </div>
          </div>

          <div className="markets__indices">
            {INDICES.map(index => (
              <article className="markets__index" key={index.key}>
                <header className="markets__index-head">
                  <span className="markets__index-name">{index.benchmark}</span>
                  {index.isProxy && (
                    <span className="markets__proxy" title={`Quoted via ${index.symbol}`}>
                      via {index.symbol}
                    </span>
                  )}
                </header>

                <div className="markets__index-value">{num(index.value, 2)}</div>

                <div className="markets__index-foot">
                  <Delta value={index.changePct} percent digits={2} />
                  <Sparkline
                    values={(index.bars || []).slice(-60).map(b => b.close)}
                    direction={index.direction}
                    width={96}
                    height={26}
                    showArea
                  />
                </div>
              </article>
            ))}
          </div>
        </section>

        {/* --------------------------------------------------------- breadth */}
        <section className="section">
          <div className="section__head">
            <div className="section__heading">
              <h2 className="section__title">Breadth</h2>
              <p className="section__subtitle">
                How much of the universe is participating. An index can rise while most of
                its names fall — breadth is what tells the two apart.
              </p>
            </div>
          </div>

          <div className="markets__metrics">
            <MetricCard
              label="Advancing"
              value={breadth.advancing}
              meta={`of ${breadth.total} names`}
              tone={breadth.pct >= 50 ? "up" : "neutral"}
              bar={breadth.pct}
            />
            <MetricCard
              label="Declining"
              value={breadth.declining}
              meta={`of ${breadth.total} names`}
              tone={breadth.pct < 50 ? "down" : "neutral"}
              bar={100 - breadth.pct}
            />
            <MetricCard
              label="Participation"
              value={breadth.pct}
              unit="%"
              meta="advancing share"
              tone={breadth.pct >= 50 ? "up" : "down"}
              bar={breadth.pct}
            />
            <MetricCard
              label="Signal sentiment"
              value={sentiment.pct}
              unit="%"
              meta={`${sentiment.bullish} of ${sentiment.total} signals bullish`}
              tone={sentiment.pct >= 50 ? "up" : "down"}
              bar={sentiment.pct}
              footnote={sentiment.label}
            />
          </div>
        </section>

        {/* ------------------------------------------------- leaders/laggards */}
        <section className="section">
          <div className="markets__movers">
            <Panel title="Leading" subtitle="Strongest moves in the universe today">
              <ul className="markets__movers-list">
                {leaders.map(r => (
                  <li className="markets__mover" key={r.symbol}>
                    <Identity symbol={r.symbol} name={r.name} />
                    <Delta value={r.changePct} percent digits={2} />
                  </li>
                ))}
              </ul>
            </Panel>

            <Panel title="Lagging" subtitle="Weakest moves in the universe today">
              <ul className="markets__movers-list">
                {laggards.map(r => (
                  <li className="markets__mover" key={r.symbol}>
                    <Identity symbol={r.symbol} name={r.name} />
                    <Delta value={r.changePct} percent digits={2} />
                  </li>
                ))}
              </ul>
            </Panel>
          </div>
        </section>

        {/* -------------------------------------------------------- universe */}
        <section className="section">
          <div className="section__head">
            <div className="section__heading">
              <h2 className="section__title">The universe</h2>
              <p className="section__subtitle">Every name the platform scans. {source.label}</p>
            </div>
            <Link className="btn btn--secondary btn--sm" to="/scanner/">
              Open the scanner
            </Link>
          </div>

          <Panel flush>
            <DataTable
              columns={columns}
              rows={rows}
              rowKey={r => r.symbol}
              initialSort={{ key: "changePct", direction: "desc" }}
              minWidth={900}
            />
          </Panel>
        </section>
      </div>
    </Shell>
  )
}

export const Head = () => <title>Markets · MarketScan</title>
